// ═══ wait()/notify() — classic, ONE wait-set ═══
Object lock = new Object();
Queue<String> queue = new LinkedList<>();

// Consumer:
synchronized (lock) {
    while (queue.isEmpty()) {
        lock.wait();           // releases lock, enters wait-set
    }
    String item = queue.poll();
}

// Producer:
synchronized (lock) {
    queue.add("TRD-001");
    lock.notify();              // wakes ONE thread from wait-set
    // lock.notifyAll();        // wakes ALL — safer but wasteful
}
// Problem: if both producers (waiting for space) and consumers (waiting for data)
// use the same object → notify() might wake a producer instead of a consumer!

// ═══ RULES for wait/notify ═══
// 1. MUST be inside synchronized(obj) — else IllegalMonitorStateException!
// 2. ALWAYS use while loop, not if — "spurious wake-up" is allowed by JMM
// 3. Prefer notifyAll() over notify() — notify() might wake wrong thread
// 4. wait() releases the lock; when it returns, lock is re-acquired

// ═══ Condition.await()/signal() — modern, MULTIPLE wait-sets ═══
ReentrantLock lock2 = new ReentrantLock();
Condition notEmpty = lock2.newCondition();  // consumers wait here
Condition notFull = lock2.newCondition();   // producers wait here

// Consumer:
lock2.lock();
try {
    while (queue.isEmpty()) {
        notEmpty.await();       // releases lock, waits on notEmpty condition
    }
    String item = queue.poll();
    notFull.signal();           // wake a PRODUCER (specific condition!)
} finally { lock2.unlock(); }

// Producer:
lock2.lock();
try {
    while (queue.size() >= MAX) {
        notFull.await();        // wait on notFull condition
    }
    queue.add("TRD-001");
    notEmpty.signal();          // wake a CONSUMER (specific condition!)
} finally { lock2.unlock(); }

// ═══ COMPARISON ═══
// Feature              wait/notify           Condition
// Lock type            synchronized          ReentrantLock
// Wait-sets            ONE per object        MULTIPLE per lock
// Targeted wake-up     NO (wakes any)        YES (signal specific condition)
// Timeout              wait(millis) — clunky  await(time, unit) — clean
// Interruptible        always (wait throws IE) awaitUninterruptibly() option
// Spurious wake-up     possible              possible (use while loop!)
// Must hold lock?      YES (synchronized)    YES (lock.lock())
