// ─── File: src/test/java/com/bank/waitnotify/WaitNotifyVsConditionTest.java ───
package com.bank.waitnotify;

import org.junit.jupiter.api.Test;
import java.util.*;
import java.util.concurrent.*;
import java.util.concurrent.locks.*;
import static org.assertj.core.api.Assertions.*;

class WaitNotifyVsConditionTest {

    // ═══ Classic wait/notify — producer/consumer ═══
    @Test
    void waitNotify_producerConsumer() throws InterruptedException {
        Object lock = new Object();
        Queue<String> queue = new LinkedList<>();
        String[] consumed = {null};
        CountDownLatch done = new CountDownLatch(1);

        // Consumer:
        Thread consumer = new Thread(() -> {
            synchronized (lock) {
                try {
                    while (queue.isEmpty()) lock.wait();
                    consumed[0] = queue.poll();
                } catch (InterruptedException e) { }
            }
            done.countDown();
        });
        consumer.start();
        Thread.sleep(100);

        // Producer:
        synchronized (lock) {
            queue.add("TRD-001");
            lock.notify();
        }

        done.await(2, TimeUnit.SECONDS);
        assertThat(consumed[0]).isEqualTo("TRD-001");
    }

    // ═══ wait outside synchronized → IllegalMonitorStateException ═══
    @Test
    void wait_outsideSync_throwsIMSE() {
        Object lock = new Object();
        assertThatThrownBy(() -> lock.wait())
            .isInstanceOf(IllegalMonitorStateException.class);
    }

    // ═══ Condition — targeted signal ═══
    @Test
    void condition_targetedSignal() throws InterruptedException {
        ReentrantLock lock = new ReentrantLock();
        Condition notEmpty = lock.newCondition();
        Queue<String> queue = new LinkedList<>();
        String[] consumed = {null};
        CountDownLatch done = new CountDownLatch(1);

        // Consumer waits on notEmpty:
        Thread consumer = new Thread(() -> {
            lock.lock();
            try {
                while (queue.isEmpty()) notEmpty.await();
                consumed[0] = queue.poll();
            } catch (InterruptedException e) { }
            finally { lock.unlock(); }
            done.countDown();
        });
        consumer.start();
        Thread.sleep(100);

        // Producer signals notEmpty:
        lock.lock();
        try {
            queue.add("TRD-001");
            notEmpty.signal();  // wakes ONLY threads waiting on notEmpty!
        } finally { lock.unlock(); }

        done.await(2, TimeUnit.SECONDS);
        assertThat(consumed[0]).isEqualTo("TRD-001");
    }

    // ═══ Bounded buffer with TWO Conditions ═══
    static class BoundedBuffer<T> {
        private final Queue<T> queue = new LinkedList<>();
        private final int capacity;
        private final ReentrantLock lock = new ReentrantLock();
        private final Condition notEmpty = lock.newCondition();
        private final Condition notFull = lock.newCondition();

        BoundedBuffer(int capacity) { this.capacity = capacity; }

        void put(T item) throws InterruptedException {
            lock.lock();
            try {
                while (queue.size() >= capacity) notFull.await();
                queue.add(item);
                notEmpty.signal();
            } finally { lock.unlock(); }
        }

        T take() throws InterruptedException {
            lock.lock();
            try {
                while (queue.isEmpty()) notEmpty.await();
                T item = queue.poll();
                notFull.signal();
                return item;
            } finally { lock.unlock(); }
        }
    }

    @Test
    void boundedBuffer_producerConsumer() throws InterruptedException {
        BoundedBuffer<String> buffer = new BoundedBuffer<>(5);
        CountDownLatch latch = new CountDownLatch(10);

        // 5 producers:
        for (int i = 0; i < 5; i++) {
            final int id = i;
            new Thread(() -> {
                try { buffer.put("TRD-" + id); } catch (InterruptedException e) { }
                latch.countDown();
            }).start();
        }

        // 5 consumers:
        List<String> consumed = new CopyOnWriteArrayList<>();
        for (int i = 0; i < 5; i++) {
            new Thread(() -> {
                try { consumed.add(buffer.take()); } catch (InterruptedException e) { }
                latch.countDown();
            }).start();
        }

        latch.await(5, TimeUnit.SECONDS);
        assertThat(consumed).hasSize(5);
    }
}
